Row(
    modifier = Modifier.fillMaxWidth(),
    verticalAlignment = Alignment.CenterVertically,
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
) {
    Box(
        modifier = Modifier
            .size(MonarchTheme.spacing.space8)
            .background(MonarchTheme.colors.bgMuted, MonarchTheme.shapes.md),
        contentAlignment = Alignment.Center,
    ) {
        MonarchText(text = "R", style = MonarchTextStyle.Label)
    }
    Row(
        modifier = Modifier.weight(1f).horizontalScroll(rememberScrollState()),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        listOf("overview" to "Overview", "projects" to "Projects").forEach { (key, label) ->
            val active = current == key
            Row(
                modifier = Modifier
                    .clip(MonarchTheme.shapes.md)
                    .background(if (active) MonarchTheme.colors.accentSubtle else Color.Transparent)
                    .selectable(selected = active, role = Role.Tab, onClick = { current = key })
                    .heightIn(min = MonarchTheme.spacing.space10)
                    .padding(horizontal = MonarchTheme.spacing.space2),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
            ) {
                MonarchText(
                    text = label,
                    style = MonarchTextStyle.Label,
                    color = if (active) MonarchTheme.colors.accentStrong else MonarchTheme.colors.textMuted,
                )
                if (key == "projects") MonarchBadge(text = "3", tone = MonarchTone.Danger, variant = MonarchBadgeVariant.Solid)
            }
        }
        Box {
            MonarchButton(
                text = "More",
                onClick = { more = true },
                variant = MonarchButtonVariant.Ghost,
                trailingIcon = { MonarchIcon(SampleIcons.ChevronDown, contentDescription = null, size = MonarchIconSize.Sm) },
            )
            MonarchMenu(expanded = more, onDismissRequest = { more = false }) {
                listOf("Calendar", "Reports", "People", "Settings").forEach { label ->
                    MonarchMenuItem(text = label, onClick = { more = false })
                }
            }
        }
    }
    MonarchButton(text = "Share", onClick = {}, size = MonarchButtonSize.Sm)
}

