examples.setup:
var current by remember { mutableIntStateOf(0) }
val destinations = listOf("Home" to SampleIcons.Home, "Search" to SampleIcons.Search, "Inbox" to SampleIcons.Inbox)
val inboxBadge: @Composable () -> Unit = { Badge { Text("3") } }

examples.code:
NavigationSuiteScaffold(
    navigationSuiteItems = {
        destinations.forEachIndexed { index, (name, icon) ->
            item(
                selected = current == index,
                onClick = { current = index },
                icon = { Icon(icon, contentDescription = null) },
                label = { Text(name) },
                badge = if (name == "Inbox") inboxBadge else null,
            )
        }
    },
) {
    MonarchText(text = destinations[current].first, style = MonarchTextStyle.Heading)
}
